import {campaignRecap} from './campaign-recap.js';
import {PACKS,legend,MANAGERS,CATALOG_COVERAGE} from './legends.js';
import {FORMATIONS} from './engine.js';
import {POSITION_SLOTS,positionLabel} from './player-positions.js';
import {assignSlots,openRoles,filterCards} from './draft.js';
import {standings,upcomingFixtures} from './competition.js';
import {escapeHtml as esc,clubBadge} from './ui-kit.js';
import {draftPhoto} from './draft-photos.js';

const button=(name,action,value='',style='secondary',extra='')=>`<button class="btn ${style||'secondary'}" data-action="eu-${action}" ${value!==''&&value!==undefined?`data-value="${esc(value)}"`:''} ${extra}>${esc(name)}</button>`;
const views=new Map(),tabs=['overview','table','fixtures','bracket','squad'];
const identity=e=>[e.seed||'home',e.format||'europe',e.type||'players'].join(':');
const viewKey=e=>'touchline.draft-view.'+(new URLSearchParams(globalThis.location?.search||'').has('qa')?'qa.':'')+'v1:'+identity(e);
export function studioView(e){const id=identity(e);if(views.has(id))return views.get(id);let saved={};try{saved=JSON.parse(globalThis.localStorage?.getItem(viewKey(e))||'{}')||{};}catch{}const v={query:'',panel:'picks',tab:tabs.includes(saved.tab)?saved.tab:'overview',slot:null};views.set(id,v);return v;}
export function updateStudioView(e,patch){const v=studioView(e);Object.assign(v,patch);if(!tabs.includes(v.tab))v.tab='overview';if(!['picks','xi'].includes(v.panel))v.panel='picks';try{globalThis.localStorage?.setItem(viewKey(e),JSON.stringify({tab:v.tab}));}catch{}return v;}
export const resetStudioView=e=>updateStudioView(e,{query:'',panel:'picks',tab:'overview',slot:null});
const stageName=c=>c.stage==='league'?(c.format==='league'?'League season':'League phase'):c.stage==='complete'?'Complete':c.stage;
const formatName=e=>e.format==='league'?'Classic season':e.type==='clubs'?'Club cup':'Champions League';
const steps=(active)=>`<ol class="draft-flow" aria-label="Draft progress">${['Reveal & pick','Appoint coach','Play your competition'].map((s,i)=>`<li ${i===active?'aria-current="step"':''}><b>${i+1}</b>${s}</li>`).join('')}</ol>`;
const header=(kicker,title,copy,actions='')=>`<header class="draft-page-header"><div><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1>${copy?`<p>${esc(copy)}</p>`:''}</div><div class="draft-header-actions">${actions}<a class="draft-photo-credit-link" href="./assets/portraits/credits.html" target="_blank" rel="noopener">Photo credits</a></div></header>`;

export function draftHome(e){
 const years=[...new Set(PACKS.map(p=>p.year))].sort((a,b)=>b-a),resume=[];
 if(e.formation&&((e.type==='players'&&e.picks?.length<11)||(e.type==='clubs'&&e.clubs?.length<8)))resume.push(['Draft in progress',`${e.type==='clubs'?e.clubs.length+'/8 clubs':e.picks.length+'/11 players'} · ${e.formation}`,'Resume draft','resume-draft']);
 if(e.picks?.length===11&&e.manager===null)resume.push(['Your XI is complete','Choose its coach and start the competition.','Review XI & appoint coach','resume-manager']);
 if(e.competition)resume.push([e.competition.champion?'Last run saved':'Competition in progress',e.competition.teams.find(t=>t.id===e.competition.user)?.name||e.name,e.competition.champion?'View last run':'Resume competition','resume']);
 return header('DRAFT & EUROPE','Build an XI. Make a run.','Historic squads, your choices, one team to take all the way.')+
 resume.map(([title,copy,label,a])=>`<section class="card draft-resume"><div><span class="eyebrow">SAVED ON THIS DEVICE</span><h2>${esc(title)}</h2><p>${esc(copy)}</p></div>${button(label,a,'','primary')}</section>`).join('')+
 `<div class="draft-home-grid"><section class="card draft-launch"><span class="draft-launch-number">01 / THE EUROPEAN RUN</span><div class="draft-launch-icon" aria-hidden="true">✦</div><h2>Champions League</h2><p>Draft eleven players from club-era squads, appoint a coach and enter a 36-club competition.</p><div class="draft-launch-actions">${button('Start Champions League draft','start','','primary')}${button('Champions League IQ · ratings hidden','iq','','ghost')}</div><small>8 league opponents · two-legged knockouts · one final</small></section><section class="card draft-launch classic-launch"><span class="draft-launch-number">02 / THE PERFECT SEASON</span><div class="draft-launch-icon" aria-hidden="true">38</div><h2>Classic season</h2><p>Your drafted XI against nineteen historic clubs. Build a balanced side and chase an unbeaten season.</p><div class="draft-launch-actions">${button('Draft a perfect season','classic','','primary')}</div><small>20 clubs · 38 matchdays · home and away</small></section></div>
 <section class="card draft-configuration"><div><span class="eyebrow">YOUR NEXT DRAFT</span><h2>Set up your team</h2><p>These choices apply when you start a new draft above.</p></div><div class="draft-setup-grid"><label>Your club name<input id="eu-name" maxlength="28" value="Your XI" placeholder="Your XI"></label><label>Formation<select id="eu-formation">${Object.keys(FORMATIONS).map(f=>`<option>${f}</option>`).join('')}</select></label><label>Represent a club<select id="eu-host">${[...new Set(PACKS.map(p=>p.club))].map(n=>`<option ${n==='Real Madrid'?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Available season<select id="eu-year"><option value="">All available years · 1990–2026</option>${years.map(y=>`<option value="${y}">${y} · ${PACKS.filter(p=>p.year===y).length} squads</option>`).join('')}</select></label><label>Competition field<select id="eu-field"><option value="icons">European Icons · historic giants</option><option value="current">2026–27 qualifiers · current squads</option></select></label></div></section>
 <div class="draft-challenge-grid"><section class="card"><span class="eyebrow">DAILY & WEEKLY</span><h2>A fresh set of draws</h2><p>Seeded challenges, visible ratings and two rerolls.</p>${button('Play daily draft','daily')}${button('This week’s draft','weekly','','ghost')}</section><section class="card"><span class="eyebrow">CLUB CUP</span><h2>Draft the whole club</h2><p>Eight club picks. Your first pick is the team you control.</p>${button('Draft clubs','clubs')}</section></div>
 <section class="card draft-historic-start"><div><span class="eyebrow">HISTORIC SQUAD SHORTCUT</span><h2>Take a great XI into Europe</h2><p>Skip the draft and go straight to appointing your coach.</p></div><label>Club & era<select id="ucl-pack">${PACKS.map(p=>`<option value="${p.id}">${esc(p.club)} · ${esc(p.era)}</option>`).join('')}</select></label>${button('Use this historic squad','club-era')}</section>
 <details class="card draft-provenance"><summary>Ratings, squad coverage & sources</summary><p>Touchline ratings and strengths are authored game values. Historical squads use linked match sheets; current squads use dated roster references. The competition uses fantasy seeding, not an official UEFA draw. Player photos may show a different year or kit; unavailable photos are labelled.</p><a href="./assets/portraits/credits.html" target="_blank" rel="noopener">Player photo credits</a><details><summary>Available years for all featured clubs</summary><div class="catalog-coverage">${CATALOG_COVERAGE.map(c=>`<div><strong>${esc(c.club)}</strong><span>${c.years.join(' · ')}</span></div>`).join('')}</div></details><details><summary>Explore the squad catalog</summary><div class="catalog-grid">${PACKS.map(p=>`<a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.club)} <span>${esc(p.era)}</span></a>`).join('')}</div></details></details>
 ${e.history.length?`<section class="card draft-history"><h2>Recent runs</h2>${e.history.slice(-5).reverse().map(h=>`<div class="fixture"><strong>${esc(h.name)}</strong><span>${esc(h.format)} · ${esc(h.result)}</span></div>`).join('')}</section>`:''}`;
}

export function draftPlayer(p,{hidden=false,reason='',extra='',action='pick'}={}){
 return `<button class="legend-card draft-player-row" data-action="eu-${action}" data-value="${esc(p.id)}" style="--club:${p.color}" ${extra} ${reason?'disabled':''}><span class="legend-portrait draft-row-art">${draftPhoto(p)}</span><span class="draft-row-identity"><strong>${esc(p.name)}</strong><small>${esc(positionLabel(p))} · ${esc(p.club)} · ${esc(p.era)}</small><span class="legend-speciality">${p.role==='GK'?'REACTION · DISTRIBUTION':p.role==='DEF'?'READING · RECOVERY':p.role==='MID'?'VISION · CONTROL':'MOVEMENT · FINISHING'}</span>${reason?`<span class="eligibility-note">${esc(reason)}</span>`:''}</span><span class="draft-row-rating"><b>${hidden?'?':p.rating}</b><small>OVR</small></span><span class="legend-attributes">${[['ATT',p.attack],['DEF',p.defense],['CTL',p.control],['STA',p.stamina]].map(([name,value])=>`<span><b>${hidden?'?':Math.round(value)}</b><small>${name}</small></span>`).join('')}</span><span class="draft-row-add" aria-hidden="true">+</span></button>`;
}
export function draftPitch(e,team=null){
 const formation=team?.formation||e.formation,slots=team?.xi||assignSlots(e.picks||[],formation,e.positionRulesVersion),roster=team?.roster,labels=e.positionRulesVersion===2?POSITION_SLOTS[formation]:FORMATIONS[formation].map(p=>p.role);
 return `<div class="draft-formation-pitch ${FORMATIONS[formation].filter(s=>s.role==='DEF').length===5?'draft-five-back':''}" role="group" aria-label="${esc(formation)} formation"><div class="draft-pitch-markings" aria-hidden="true"><i></i><i></i><i></i></div>${FORMATIONS[formation].map((slot,i)=>{const p=roster?roster.find(p=>p.id===slots[i]):legend(slots[i]),label=labels?.[i]||slot.role;return `<button class="draft-pitch-slot ${p?'filled':''}" style="left:${Math.max(12,Math.min(88,slot.x))}%;top:${slot.y}%" data-action="eu-ui-slot" data-value="${i}" aria-label="${esc(label+(p?' · '+p.name:' · open position'))}" aria-pressed="${studioView(e).slot===i}"><span class="draft-pitch-position">${esc(label)}</span>${p?`<span class="draft-pitch-art">${draftPhoto(p)}</span><strong>${esc(p.name.split(' ').at(-1))}</strong><small>${e.hidden&&e.phase==='draft'?'?':p.rating} <span>OVR</span></small>`:'<span class="draft-empty-plus" aria-hidden="true">+</span>'}</button>`;}).join('')}</div>`;
}
export function draftWorkspace(e,{clubById}){
 const clubMode=e.type==='clubs',roles=openRoles(e.picks||[],e.formation,e.positionRulesVersion),count=clubMode?e.clubs.length:e.picks.length,total=clubMode?8:11,pack=PACKS.find(p=>p.id===e.roll),v=studioView(e),role=roles.includes(e.roleFilter)?e.roleFilter:'ALL',options=clubMode?e.clubOptions||[]:filterCards(pack?.players||[],e.picks,e.formation,{role,minimum:e.minRating||0,sort:e.cardSort,hidden:e.hidden,version:e.positionRulesVersion}),shown=clubMode?options:options.filter(p=>!v.query||[p.name,p.club,p.era].join(' ').toLowerCase().includes(v.query.toLowerCase()));
 const slotPlayer=Number.isInteger(v.slot)?legend(assignSlots(e.picks||[],e.formation,e.positionRulesVersion)[v.slot]):null;
 return header(formatName(e),clubMode?'Choose your contenders':'Your next pick',`${e.daily?'Daily '+e.day+' · ':e.weekly?'Weekly challenge · ':''}${count} / ${total} ${clubMode?'clubs':'players'} selected · ${e.formation} · ${e.hidden?'IQ · ratings hidden':'Classic · ratings visible'}`,button('Leave draft','home','','ghost'))+steps(0)+
 `<div class="draft-mobile-switch" role="tablist" aria-label="Draft workspace">${['picks','xi'].map((p,i)=>button(p==='picks'?(clubMode?'Club choices':'Player choices'):(clubMode?'Your clubs · ':'Your XI · ')+count+'/'+total,'ui-panel',p,v.panel===p?'primary':'ghost',`role="tab" aria-selected="${v.panel===p}" aria-controls="draft-${p}-panel" id="draft-mobile-${p}" tabindex="${v.panel===p?0:-1}"`)).join('')}</div><div class="draft-layout draft-workspace" data-mobile-panel="${v.panel}">
 <section class="draft-picks" id="draft-picks-panel" aria-label="Draft choices"><section class="spin-panel card ${pack||e.clubOptions?'revealed':''}"><div class="draft-reveal-slots"><div><span class="eyebrow">${clubMode?'CLUB DRAW':'CLUB'}</span><h2>${pack?esc(pack.club):clubMode?'Your next club':'Unknown club'}</h2></div><div><span class="eyebrow">${clubMode?'FIELD':'ERA'}</span><strong class="era-reveal">${pack?esc(pack.era):clubMode?'8 places':'—'}</strong></div></div><div class="draft-reveal-action">${button(e.roll||e.clubOptions?'Reroll · '+e.rerolls+' left':'Reveal '+(clubMode?'clubs':'a club & era'),'spin','','primary',`${(e.roll||e.clubOptions)&&e.rerolls<=0?'disabled':''} data-draft-next`)}<small>${pack?`${options.length} eligible players · pick one to continue`:clubMode?'Your first club is the team you control.':'Reveal a club-era squad, then pick one eligible player.'}</small></div></section>
 ${!clubMode?`<div class="draft-open-positions"><span>Still needed</span>${roles.map(r=>button(r,'ui-position',r,role===r?'primary':'ghost',`aria-pressed="${role===r}"`)).join('')}</div>`:''}
 ${pack&&!clubMode?`<section class="draft-filter-bar card"><label class="draft-player-search">Search this squad<input id="draft-search" type="search" placeholder="Player name…" value="${esc(v.query)}" autocomplete="off"></label><details class="draft-advanced"><summary>Position, sort & rating filters</summary><div><label>Position<select id="draft-role"><option value="ALL">All open positions</option>${roles.map(r=>`<option value="${r}" ${role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Sort cards<select id="draft-sort"><option value="source">Squad order</option><option value="name" ${e.cardSort==='name'?'selected':''}>Name</option>${e.hidden?'':`<option value="high" ${e.cardSort==='high'?'selected':''}>OVR · highest first</option><option value="low" ${e.cardSort==='low'?'selected':''}>OVR · lowest first</option>`}</select></label>${e.hidden?'<span class="draft-iq-note">IQ · all player ratings hidden</span>':`<label>Minimum OVR<input id="draft-min" type="number" min="0" max="99" value="${e.minRating||0}"></label>`}</div></details></section><p class="draft-choice-count" role="status">${shown.length} choices${v.query?' matching “'+esc(v.query)+'”':''}</p>`:''}
 <div class="legend-grid draft-player-list">${clubMode?shown.map(t=>`<button class="club-draft-card card" data-action="eu-pickclub" data-value="${esc(t.id)}">${clubBadge(t.name,t.color)}<strong>${esc(t.name)}</strong><span>${esc(t.era||t.country||'Historic club')}</span><b>${t.rating} OVR</b></button>`).join(''):shown.map(p=>draftPlayer(p,{hidden:e.hidden})).join('')}</div>
 ${pack&&!shown.length?`<section class="draft-empty card"><h3>No players match these filters</h3><p>Clear the search or choose another open position. Your reveal and picks are preserved.</p>${button('Clear search & filters','ui-clear-search')}</section>`:!pack&&!e.clubOptions?'<section class="draft-empty card"><span class="eyebrow">READY WHEN YOU ARE</span><h3>One reveal. Your choice.</h3><p>Your formation stays alongside your choices. Filled positions and duplicate players are excluded from new offers.</p></section>':''}
 ${!clubMode&&e.catalogYear?`<div class="draft-year-note">${e.catalogYear} only · ${button('Open all years','all-years','','ghost')}</div>`:''}</section>
 <aside class="card draft-squad" id="draft-xi-panel"><header><div><span class="eyebrow">YOUR TEAM</span><h2>${esc(e.name)}</h2></div><span class="badge lime">${count} / ${total}</span></header><div class="draft-progress" role="progressbar" aria-label="Draft picks" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${count}"><i style="width:${count/total*100}%"></i></div>${clubMode?e.clubs.map(clubById).map((t,i)=>`<div class="fixture">${clubBadge(t.name,t.color)}<strong>${esc(t.name)}</strong>${i===0?'<small>YOUR CLUB</small>':''}</div>`).join(''):draftPitch(e)}${slotPlayer?`<section class="draft-slot-info"><h3>${esc(slotPlayer.name)}</h3><p>${esc(positionLabel(slotPlayer))} · ${esc(slotPlayer.club)} · ${esc(slotPlayer.era)}</p></section>`:''}<p class="stat-foot">${clubMode?'Eight clubs · one-leg knockout ties':`${e.formation} · seven reserves added after your XI. Tap an open position to filter players.`}</p><details><summary>Selection rules</summary><p>No duplicate people. New drafts use specific-position eligibility; older runs keep their saved rules. Reveal and reroll allowances are unchanged. Ratings and tactical interpretations are authored Touchline values.</p></details></aside></div>`;
}

export function draftCoach(e,{ratingTeam}){
 const strength=ratingTeam(e.picks),pool=e.picks.map(legend),units=['DEF','MID','FWD'].map(role=>{const ps=pool.filter(p=>p.role===role);return {role,r:ps.length?ps.reduce((n,p)=>n+p.rating,0)/ps.length:0};}).sort((a,b)=>a.r-b.r);
 return header('YOUR XI IS COMPLETE','Choose its identity','Appoint a coach to start your competition.')+steps(1)+`<div class="draft-coach-layout"><section><div class="card draft-coach-summary"><div><span class="eyebrow">${esc(e.name)}</span><h2>${e.formation} · ready to play</h2></div><div><b>${strength.rating}</b><small>Squad OVR</small></div><div><b>${strength.chemistry}</b><small>Club familiarity</small></div></div><p class="draft-coach-tip">Your ${units[0].role==='DEF'?'defence':units[0].role==='MID'?'midfield':'attack'} is the lowest-rated unit (${Math.round(units[0].r)}). Choose an approach that fits the team you built.</p><div class="manager-grid draft-coach-choices">${MANAGERS.map(m=>`<button class="manager-choice card" data-action="eu-manager" data-value="${m.id}"><span class="manager-portrait"><img src="./assets/studio-coaches/${m.id}.svg" alt="" loading="lazy"></span><span><small>${esc(m.style)}</small><h2>${esc(m.name)}</h2><p>${esc(m.description)}</p><small>${m.id==='hunter'?'More pressure · faster energy use':m.id==='guardian'?'Deeper block · less forward support':'Balanced support · patient build-up'}</small></span><b>Appoint coach →</b></button>`).join('')}</div></section><aside class="card draft-squad"><header><h2>Your completed XI</h2><span class="badge lime">11 / 11</span></header>${draftPitch(e)}<details><summary>Full squad names & positions</summary><div class="completed-grid">${assignSlots(e.picks,e.formation,e.positionRulesVersion).map((id,i)=>`<span><b>${e.positionRulesVersion===2?POSITION_SLOTS[e.formation][i]:legend(id).role}</b> ${esc(legend(id).name)}</span>`).join('')}</div></details></aside></div>`;
}

export function campaignSummary(c){
 const rows=standings(c),me=rows.find(t=>t.id===c.user),rank=rows.findIndex(t=>t.id===c.user)+1,played=c.results.filter(r=>r.home===c.user||r.away===c.user);let qualification='';
 if(c.format==='clubcup')for(const r of played){const side=r.home===c.user?0:1;me.p++;me.gf+=r.score[side];me.ga+=r.score[1-side];if(r.winner===c.user)me.w++;else me.l++;}
 if(c.format==='europe')qualification=me.p===8?(rank<=8?'Qualified directly for the round of 16':rank<=24?'League phase complete · knockout playoff place':'League phase complete · eliminated'):'Top 8 advance directly · 9–24 enter playoffs · 25–36 go out';
 return {me,rank:me.p&&c.format!=='clubcup'?rank:null,played,qualification};
}
function campaignBracket(c){const stages=c.format==='clubcup'?['Quarter-finals','Semi-finals','Final']:['Play-offs','Round of 16','Quarter-finals','Semi-finals','Final'],name=id=>c.teams.find(t=>t.id===id)?.name||id;return `<div class="campaign-bracket" tabindex="0" role="region" aria-label="Knockout rounds · scroll horizontally">${stages.map(stage=>{const results=c.results.filter(r=>r.stage===stage),groups=new Map();for(const r of results){const key=[r.home,r.away].sort().join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}if(c.stage===stage)for(const [a,b]of c.ties)if(!groups.has([a,b].sort().join('|')))groups.set([a,b].sort().join('|'),[{home:a,away:b,pending:true}]);return `<section class="campaign-bracket-round"><h3>${esc(stage)}</h3>${[...groups.values()].map(legs=>{const first=legs[0],last=legs.at(-1),home=first.home,away=first.away,aggregate=last.aggregate?(last.aggregateHome===home?last.aggregate:[...last.aggregate].reverse()):legs.filter(r=>!r.pending).reduce((s,r)=>[s[0]+r.score[r.home===home?0:1],s[1]+r.score[r.home===home?1:0]],[0,0]);return `<article class="campaign-tie ${home===c.user||away===c.user?'mine':''}"><div><strong>${esc(name(home))}</strong><b>${first.pending?'—':aggregate[0]}</b></div><div><strong>${esc(name(away))}</strong><b>${first.pending?'—':aggregate[1]}</b></div><small>${first.pending?'Draw confirmed · next tie':last.pens?'Penalties · '+esc(name(last.tieWinner||last.penaltyWinner||last.winner))+' through':legs.length===1&&c.format!=='clubcup'&&stage!=='Final'?'First leg · second leg to play':stage==='Final'?'Final result':'Tie recorded'}</small></article>`;}).join('')||'<p class="campaign-undrawn">Draw not made yet</p>'}</section>`;}).join('')}</div>`;}
export function draftCampaign(e,{table,resultRows}){
 const c=e.competition,v=studioView(e),user=c.teams.find(t=>t.id===c.user),champ=c.teams.find(t=>t.id===c.champion),summary=campaignSummary(c),next=upcomingFixtures(c).find(f=>f.home===c.user||f.away===c.user),opp=next?c.teams.find(t=>t.id===(next.home===c.user?next.away:next.home)):null,active=tabs.includes(v.tab)?v.tab:'overview',mine=summary.played;
 const fixtureCard=`<section class="card campaign-next"><div><span class="eyebrow">${c.champion?'COMPETITION COMPLETE':c.eliminated?'YOUR RUN IS OVER':e.pending?.context==='draft'?'SAVED LIVE FIXTURE':'NEXT FIXTURE'}</span><h2>${c.champion?esc(champ.name)+' · champions':next?esc(user.name)+' vs '+esc(opp.name):c.eliminated?'Follow the competition to its conclusion':esc(stageName(c))}</h2><p>${next?(next.home===c.user?'Home':'Away')+' · '+(c.stage==='league'?'Matchday '+(c.round+1)+' / '+c.schedule.length:esc(c.stage)+' · '+(c.format==='clubcup'||c.stage==='Final'?'single match':'leg '+next.leg)):c.champion?'Your result and match records are saved on this device.':'You can finish the remaining ties and discover the champion.'}</p></div><div class="campaign-match-actions">${!c.champion?`${next&&c.engineVersion==='2.0.0'?`${!e.pending||e.pending.context==='draft'&&e.pending.definition?.controlVersion===1?button(e.pending?'Resume playing':'Play yourself','direct','','primary','id="eu-direct"'):''}${button(e.pending?.fixture?.seed===next.seed?'Resume live fixture':'Manage live','manage','','secondary','id="eu-manage"')}`:''}${button(next?'Simulate matchday':'Continue competition','advance','',next?'secondary':'primary','id="eu-advance"')}${button(c.format==='league'?'Simulate remaining league':c.format==='clubcup'?'Simulate remaining cup':'Simulate remaining Champions League','season-fast','','ghost')}`:button('Draft another team','home','','primary')}</div></section>`;
 const records=`<section class="card campaign-records"><h2>Recorded matches</h2>${c.results.map((m,i)=>({m,i})).filter(({m})=>m.definition&&m.engineVersion==='2.0.0').reverse().map(({m,i})=>button('Replay '+m.stage+' '+m.round+' · '+m.score.join('–')+' vs '+(c.teams.find(t=>t.id===(m.home===c.user?m.away:m.home))?.name||'opponent'),'watch-fixture',i,'ghost')).join('')||'<p>No physical replays yet. Simulated fixtures have statistical results.</p>'}</section>`;
 let panel='';
 if(active==='table')panel=`<section class="card campaign-table"><header><h2 tabindex="-1" data-campaign-focus>${c.format==='clubcup'?'The cup field':'League standings'}</h2><span>${c.format==='europe'?'Top 8 direct · 9–24 playoffs':c.format==='league'?'3 points win · 1 draw':'8 clubs · single-leg ties'}</span></header>${c.format!=='clubcup'?table(c):c.teams.map(t=>`<div class="fixture">${clubBadge(t.name,t.color)}<strong>${esc(t.name)}</strong></div>`).join('')}</section>`;
 else if(active==='fixtures')panel=`<section class="card campaign-fixtures"><h2 tabindex="-1" data-campaign-focus>Your results</h2>${resultRows(c,mine)||'<p>Your first fixture is ahead.</p>'}<details><summary>All fixtures & knockout results · ${c.results.length} played</summary>${[...new Set(c.results.map(r=>r.stage))].map(stage=>`<h3>${esc(stage)}</h3>${resultRows(c,c.results.filter(r=>r.stage===stage))}`).join('')}</details></section>${records}`;
 else if(active==='bracket')panel=`<section class="card campaign-bracket-panel"><h2 tabindex="-1" data-campaign-focus>Knockout bracket</h2><p>Confirmed draws and recorded scores. Scroll across to follow each round.</p>${c.format==='league'?'<p>Classic is a league competition without knockout ties.</p>':campaignBracket(c)}</section>`;
 else if(active==='squad')panel=`<section class="card campaign-squad"><h2 tabindex="-1" data-campaign-focus>Your match squad</h2><div class="campaign-team-layout">${draftPitch(e,user)}<div>${(user.xi||[]).map((id,i)=>{const p=user.roster?.find(p=>p.id===id);return p?`<div class="campaign-player"><b>${esc(p.assignedPosition||p.role)}</b><strong>${esc(p.name)}</strong><span>${p.rating} OVR</span></div>`:'';}).join('')}<h3>Reserves</h3>${(user.roster||[]).filter(p=>!user.xi?.includes(p.id)).map(p=>`<div class="campaign-player"><b>${esc(positionLabel(p)||p.role)}</b><strong>${esc(p.name)}</strong></div>`).join('')}</div></div></section>`;
 else panel=campaignRecap(c)+`<div class="campaign-overview"><section class="card"><h2 tabindex="-1" data-campaign-focus>${c.champion?'Your final record':'Your campaign so far'}</h2>${summary.me.p?`<div class="campaign-record"><b>${summary.me.w}<small>WINS</small></b><b>${summary.me.d}<small>DRAWS</small></b><b>${summary.me.l}<small>LOSSES</small></b></div>`:'<p>Your first fixture is ahead.</p>'}<p>${c.format==='league'?'League results':c.format==='europe'?'League-phase results':'Cup results'} · ${mine.length} club fixtures recorded.</p>${summary.qualification?`<p class="campaign-qualification">${esc(summary.qualification)}</p>`:''}${button(c.format==='clubcup'?'View cup field':'View league table','ui-tab','table')}${c.format!=='league'?button('View knockout bracket','ui-tab','bracket','',''):''}</section><section class="card"><h2>Latest club results</h2>${resultRows(c,mine.slice(-3))||'<p>Your match results will appear here.</p>'}${button('View all fixtures','ui-tab','fixtures','','')}</section></div>`;
 return header(formatName(e),user.name,`${stageName(c)} · ${user.formation||e.formation} · ${c.teams.length} clubs`,button('Draft hub','home','','ghost'))+`<div class="campaign-status"><span><small>${c.format==='clubcup'?'CUP MATCHES':'LEAGUE POSITION'}</small><b>${c.format==='clubcup'?summary.me.p:summary.rank?summary.rank+' / '+c.teams.length:'—'}</b></span><span><small>${c.format==='clubcup'?'CUP WINS':'POINTS'}</small><b>${c.format==='clubcup'?summary.me.w:summary.me.pts}</b></span><span><small>GOALS FOR / AGAINST</small><b>${summary.me.gf} / ${summary.me.ga}</b></span><span><small>STAGE</small><b>${esc(stageName(c))}</b></span></div>`+fixtureCard+`<nav class="campaign-tabs" role="tablist" aria-label="Campaign views">${[['overview','Overview'],['table',c.format==='clubcup'?'Club field':'League table'],['fixtures','Fixtures & replays'],['bracket','Knockout bracket'],['squad','Your XI']].map(([id,label])=>button(label,'ui-tab',id,active===id?'primary':'ghost',`role="tab" aria-selected="${active===id}" aria-controls="campaign-panel" id="campaign-tab-${id}" tabindex="${active===id?0:-1}"`)).join('')}</nav><div id="campaign-panel" role="tabpanel" aria-labelledby="campaign-tab-${active}">${panel}</div><div class="campaign-footer-actions">${e.type==='players'?button('Take this XI into career','career-draft'):''}${c.results.some(r=>(r.home===c.user||r.away===c.user)&&r.engineVersion!=='fast-season-1')?button('Watch last match · 3D','watch'):''}${button('Share this challenge','share','','ghost')}</div><details class="draft-provenance"><summary>Competition rules & data</summary><p>${esc(c.fieldLabel||'Preserved club field')} · authored ratings and fantasy seeding. ${c.format==='europe'?'Eight unique league opponents, four home and four away. Two-legged knockout ties and one final.':c.format==='league'?'38 matchdays, home and away.':'Eight clubs in single-leg knockout ties.'} Statistical fixtures have no physical replay. Existing runs retain their saved rules.</p></details>`;
}

export function installDraftStudio({state,render,save}){
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action^="eu-ui-"]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const s=state(),a=el.dataset.action.slice(6),value=el.dataset.value,v=studioView(s);
  if(a==='tab')updateStudioView(s,{tab:value});
  else if(a==='panel')updateStudioView(s,{panel:value});
  else if(a==='position'){s.roleFilter=value;updateStudioView(s,{query:'',panel:'picks',slot:null});save();}
  else if(a==='clear-search'){s.roleFilter='ALL';s.minRating=0;updateStudioView(s,{query:'',panel:'picks'});save();}
  else if(a==='slot'){const i=Number(value),formation=(s.phase==='competition'?s.competition.teams.find(t=>t.id===s.competition.user)?.formation:null)||s.formation,slot=s.phase==='competition'?s.competition.teams.find(t=>t.id===s.competition.user)?.xi?.[i]:assignSlots(s.picks||[],formation,s.positionRulesVersion)[i];if(s.phase==='draft'&&!slot){s.roleFilter=s.positionRulesVersion===2?POSITION_SLOTS[formation][i]:FORMATIONS[formation][i].role;updateStudioView(s,{query:'',panel:'picks',slot:null});save();}else updateStudioView(s,{slot:v.slot===i?null:i});}
  render();if(a==='tab')document.querySelector('[data-campaign-focus]')?.focus({preventScroll:true});if(a==='position'||a==='clear-search')document.querySelector('#draft-search')?.focus({preventScroll:true});
 },true);
 document.addEventListener('input',e=>{if(e.target.id!=='draft-search')return;const text=e.target.value,at=e.target.selectionStart;updateStudioView(state(),{query:text});render();const field=document.getElementById('draft-search');field?.focus({preventScroll:true});if(field&&at!==null)field.setSelectionRange(at,at);});
 document.addEventListener('keydown',e=>{if(!e.target.matches('.campaign-tabs [role=tab],.draft-mobile-switch [role=tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const all=[...e.target.closest('[role=tablist]').querySelectorAll('[role=tab]')],i=all.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length,id=all[next].id;all[next].click();document.getElementById(id)?.focus();},true);
}
